-- 0037: دمج قسم الأمن والسلامة (SAF) في الحوكمة: دليل إجراءاته H-01..H-07، القواعد R-19..R-24، محور «ط. الأمن والسلامة» في المصفوفة، نقاط التسليم، الموجّه والأسئلة، وإعادة ربط الإجراءات المشتركة (G-01، G-04، G-10، G-11، G-12) وأدلة المرافق والصيانة به.
-- كتلة التحويل تعمل مرة واحدة (علامتها غياب H-02) ثم تبقى الإدراجات قابلة لإعادة التشغيل بلا تكرار.
insert into public.gov_units(code,name,short,kind,color,mission,duties,sort) values ('SAF','قسم الأمن والسلامة','الأمن والسلامة','unit','B03A48','حماية المرضى والزوار والعاملين والممتلكات: الأمن وضبط الدخول، السلامة من الحريق واشتراطات الدفاع المدني، السلامة المهنية، المواد الخطرة، والاستعداد للطوارئ.','["الأمن والحراسات وضبط الدخول والمفاتيح والمراقبة (H-05)", "السلامة من الحريق وتعطيل أنظمته والإجراءات البديلة (H-01)", "تراخيص الدفاع المدني وفحوصه وملاحظاته (H-06)", "خطط الطوارئ والإخلاء والتمارين (H-02)", "الإبلاغ عن الحوادث والتحقيق فيها (H-03)", "المواد الخطرة وبطاقات السلامة (H-04)", "السلامة المهنية وتهيئة العاملين والمقاولين وإيقاف العمل الخطر (H-07)", "المشاركة في الجولات ولجان الاستلام وإعادة الفتح وتصاريح العمل"]'::jsonb,9) on conflict (code) do nothing;
create or replace function pg_temp.gov_recode(o text, n text) returns void language plpgsql as $f$
declare r text := '\m' || o || '\M';
begin
  update public.gov_processes set steps = regexp_replace(steps::text, r, n, 'g')::jsonb, notes = regexp_replace(notes, r, n, 'g'), goal = regexp_replace(goal, r, n, 'g'), trigger = regexp_replace(trigger, r, n, 'g')
    where steps::text ~ r or notes ~ r or goal ~ r or trigger ~ r;
  update public.gov_rules set process_code = regexp_replace(process_code, r, n, 'g'), statement = regexp_replace(statement, r, n, 'g'), criteria = regexp_replace(criteria::text, r, n, 'g')::jsonb, note = regexp_replace(note, r, n, 'g')
    where process_code ~ r or statement ~ r or criteria::text ~ r or note ~ r;
  update public.gov_faq set a = regexp_replace(a, r, n, 'g'), links = regexp_replace(links::text, r, n, 'g')::jsonb where a ~ r or links::text ~ r;
  update public.gov_router set opts = regexp_replace(opts::text, r, n, 'g')::jsonb where opts::text ~ r;
  update public.gov_handoffs set process_code = regexp_replace(process_code, r, n, 'g'), trigger = regexp_replace(trigger, r, n, 'g'), deliverable = regexp_replace(deliverable, r, n, 'g'), note = regexp_replace(note, r, n, 'g')
    where process_code ~ r or trigger ~ r or deliverable ~ r or note ~ r;
  update public.gov_activities set title = regexp_replace(title, r, n, 'g'), note = regexp_replace(note, r, n, 'g') where title ~ r or note ~ r;
  update public.gov_units set duties = regexp_replace(duties::text, r, n, 'g')::jsonb, mission = regexp_replace(mission, r, n, 'g') where duties::text ~ r or mission ~ r;
end $f$;
create or replace function pg_temp.gov_rename(o text, n text, t text) returns void language plpgsql as $f$
begin
  if exists (select 1 from public.gov_processes where code = o and title = t) and not exists (select 1 from public.gov_processes where code = n) then
    update public.gov_processes set code = n where code = o;
    perform pg_temp.gov_recode(o, n);
  end if;
end $f$;
create or replace function pg_temp.step_text(c text, a text, b text) returns void language sql as $f$
  update public.gov_processes set steps = replace(steps::text, a, b)::jsonb where code = c and position(a in steps::text) > 0;
$f$;
create or replace function pg_temp.step_unit(c text, m text, u text) returns void language sql as $f$
  update public.gov_processes p set steps = (select jsonb_agg(case when e->>'action' like '%' || m || '%' then jsonb_set(e, '{unit}', to_jsonb(u)) else e end order by i) from jsonb_array_elements(p.steps) with ordinality t(e, i))
  where code = c and exists (select 1 from jsonb_array_elements(p.steps) e where e->>'action' like '%' || m || '%');
$f$;
create or replace function pg_temp.step_after(c text, m text, s jsonb) returns void language sql as $f$
  update public.gov_processes p set steps = (select jsonb_agg(x order by ord) from (
      select e as x, i * 10 as ord from jsonb_array_elements(p.steps) with ordinality t(e, i)
      union all
      select s, (select i * 10 + 5 from jsonb_array_elements(p.steps) with ordinality t(e, i) where e->>'action' like '%' || m || '%' order by i limit 1)) z)
  where code = c and exists (select 1 from jsonb_array_elements(p.steps) e where e->>'action' like '%' || m || '%')
    and not exists (select 1 from jsonb_array_elements(p.steps) e where e->>'action' = s->>'action');
$f$;
do $$ begin
if not exists (select 1 from public.gov_processes where code = 'H-02') then
  delete from public.gov_activities a where a.scope='units' and a.title='طلب إغلاق غرفة أو عيادة أو منطقة لأعمال صيانة أو مشروع (F-01)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'طلب إغلاق غرفة أو عيادة أو منطقة لأعمال صيانة أو مشروع (%' and x.title <> 'طلب إغلاق غرفة أو عيادة أو منطقة لأعمال صيانة أو مشروع (F-01)');
  delete from public.gov_activities a where a.scope='units' and a.title='اعتماد الإغلاق بحسب مدته وحساسية المنطقة (R-12)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'اعتماد الإغلاق بحسب مدته وحساسية المنطقة (%' and x.title <> 'اعتماد الإغلاق بحسب مدته وحساسية المنطقة (R-12)');
  delete from public.gov_activities a where a.scope='units' and a.title='إصدار تصاريح العمل والعزل الآمن (M-01)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'إصدار تصاريح العمل والعزل الآمن (%' and x.title <> 'إصدار تصاريح العمل والعزل الآمن (M-01)');
  delete from public.gov_activities a where a.scope='units' and a.title='تعطيل أنظمة الحريق وإجراءات السلامة البديلة (H-01)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'تعطيل أنظمة الحريق وإجراءات السلامة البديلة (%' and x.title <> 'تعطيل أنظمة الحريق وإجراءات السلامة البديلة (H-01)');
  delete from public.gov_activities a where a.scope='units' and a.title='الإيقاف المخطط للمرافق الحيوية (M-02)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'الإيقاف المخطط للمرافق الحيوية (%' and x.title <> 'الإيقاف المخطط للمرافق الحيوية (M-02)');
  delete from public.gov_activities a where a.scope='units' and a.title='الجولات الميدانية لبيئة الرعاية (F-02)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'الجولات الميدانية لبيئة الرعاية (%' and x.title <> 'الجولات الميدانية لبيئة الرعاية (F-02)');
  delete from public.gov_activities a where a.scope='units' and a.title='سجل المواقع والأصول وحالة الغرف (F-03)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'سجل المواقع والأصول وحالة الغرف (%' and x.title <> 'سجل المواقع والأصول وحالة الغرف (F-03)');
  delete from public.gov_activities a where a.scope='units' and a.title='الاختبارات الدورية للأنظمة الحرجة (M-03)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'الاختبارات الدورية للأنظمة الحرجة (%' and x.title <> 'الاختبارات الدورية للأنظمة الحرجة (M-03)');
  delete from public.gov_activities a where a.scope='units' and a.title='تقييم مقاولي التشغيل والصيانة الشهري (M-04)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'تقييم مقاولي التشغيل والصيانة الشهري (%' and x.title <> 'تقييم مقاولي التشغيل والصيانة الشهري (M-04)');
  delete from public.gov_activities a where a.scope='units' and a.title='خطة إدارة المرافق السنوية وتقييمها (F-04)' and exists (select 1 from public.gov_activities x where x.id <> a.id and x.scope='units' and x.title like 'خطة إدارة المرافق السنوية وتقييمها (%' and x.title <> 'خطة إدارة المرافق السنوية وتقييمها (F-04)');
  perform pg_temp.gov_rename('F-02', 'H-01', 'تعطيل أنظمة السلامة من الحريق وإجراءات السلامة البديلة');
  perform pg_temp.gov_rename('F-03', 'F-02', 'الجولات الميدانية وتفتيش بيئة الرعاية');
  perform pg_temp.gov_rename('F-04', 'F-03', 'سجل المواقع والأصول وحالة الغرف');
  perform pg_temp.gov_rename('F-05', 'F-04', 'خطة إدارة المرافق السنوية وتقييمها');
  update public.gov_processes set title='إغلاق غرفة أو عيادة أو منطقة للصيانة وإعادة فتحها', owner='FAC', units='["MNT", "FAC", "BEN", "SAF", "DIR", "BME", "IT", "GEN"]'::jsonb, goal='لا تُغلق مساحة تشغيلية إلا بخطة معلنة وبديل متفق عليه للمرضى، ولا تعود إلى الخدمة إلا بفحص مشترك موثّق يثبت سلامتها ونظافتها وجاهزية أنظمتها.', trigger='أعمال صيانة مخططة أو تصحيحية أو تطوير تتطلب إخلاء غرفة أو عيادة أو منطقة، أو عطل يجعل المساحة غير آمنة للاستخدام.', inputs='نطاق الأعمال، أرقام الغرف المتأثرة، المدة المقدّرة، الأنظمة التي ستُعزل، تصنيف المنطقة (حرجة/غير حرجة).', outputs='إشعار إغلاق معتمد، لوحة «مغلق للصيانة» في الموقع، حالة الغرفة محدّثة في السجل، محضر إعادة فتح موقّع.', kpi='الالتزام بمدة الإغلاق المعلنة ≥ 90٪؛ صفر إعادة فتح دون محضر؛ متوسط مدة الإغلاق لكل نوع عمل.', steps='[{"unit": "MNT", "action": "رفع طلب الإغلاق: نطاق العمل، الغرف المتأثرة بأرقامها، المدة المقدّرة، الأنظمة التي ستُعزل، وهل يلزم تصريح عمل (M-01)", "sla": "قبل 5 أيام عمل للمخطط", "where": "نموذج طلب إغلاق", "kind": "step", "role": "مشرف الصيانة أو مهندس المشروع"}, {"unit": "FAC", "action": "تصنيف الإغلاق: جزئي أو كلي، مخطط أو طارئ، منطقة حرجة أم لا، وتحديد مستوى الاعتماد وفق R-12", "sla": "يوم عمل", "where": "سجل المساحات", "kind": "decision"}, {"unit": "BEN", "action": "الاتفاق على موعد الإغلاق والبديل: نقل العيادة، إعادة جدولة المواعيد، أو تشغيل غرفة احتياطية", "sla": "يومان", "where": "—", "kind": "step", "role": "مدير المنشأة"}, {"unit": "BEN", "action": "تقييم مخاطر العدوى (ICRA) وتحديد الفئة ومتطلبات العزل والحواجز والضغط السلبي إن لزم", "sla": "يومان", "where": "نموذج ICRA", "kind": "step", "role": "مكافحة العدوى"}, {"unit": "SAF", "action": "تقييم السلامة: مسارات الإخلاء البديلة، أثر الإغلاق على المخارج وأنظمة الحريق (وإن لزم تعطيلها H-01)، وتأمين المنطقة المغلقة", "sla": "يومان", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "اعتماد الإغلاق إذا تجاوز يومي عمل أو كان في منطقة حرجة (R-12)", "sla": "يوم عمل", "where": "—", "kind": "decision"}, {"unit": "FAC", "action": "إصدار إشعار الإغلاق للمنشأة والأقسام المعنية والأمن والسلامة، وتحديث حالة الغرفة إلى «مغلقة للصيانة» بتاريخ العودة المتوقع", "sla": "قبل الإغلاق بـ 48 ساعة", "where": "سجل المساحات", "kind": "step"}, {"unit": "BME", "action": "إخلاء الأجهزة الطبية أو حمايتها في مكانها، وتوثيق مواقعها المؤقتة", "sla": "قبل الإغلاق", "where": "سجل الأجهزة", "kind": "step"}, {"unit": "IT", "action": "فصل الأجهزة والنقاط التقنية أو حمايتها", "sla": "قبل الإغلاق", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "إخلاء الأثاث والمستلزمات، وتركيب الحواجز ولوحة «مغلق للصيانة» بتاريخ العودة المتوقع", "sla": "يوم الإغلاق", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تنفيذ الأعمال بتصريح عمل وعزل آمن (M-01)، وتحديث التقدم يومياً، وإبلاغ المرافق فوراً بأي حاجة لتمديد المدة", "sla": "حسب الخطة", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "إنهاء الأعمال واختبار الأنظمة المتأثرة وتسليم المساحة للمرافق بقائمة فحص", "sla": "فور الانتهاء", "where": "قائمة فحص إعادة الفتح", "kind": "step"}, {"unit": "GEN", "action": "التنظيف النهائي الشامل وإزالة الحواجز وإعادة الأثاث", "sla": "يوم", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "فحص النظافة وإجازة عودة المساحة للخدمة من ناحية مكافحة العدوى", "sla": "24 ساعة", "where": "—", "kind": "decision", "role": "مكافحة العدوى"}, {"unit": "FAC", "action": "جولة إعادة الفتح المشتركة (المرافق، الصيانة، الأمن والسلامة، المنشأة): السلامة من الحريق، المخارج والأبواب، الكهرباء والإنارة، التكييف، الغازات الطبية، النظافة، الأجهزة؛ توقيع المحضر أو تحرير ملاحظات بمهلة", "sla": "يوم", "where": "محضر إعادة الفتح", "kind": "decision"}, {"unit": "FAC", "action": "تحديث حالة الغرفة إلى «تشغيلية»، وإبلاغ المنشأة والأقسام بإعادة الفتح، وإغلاق الطلب", "sla": "فور التوقيع", "where": "سجل المساحات", "kind": "step"}]'::jsonb, notes='الإغلاق الطارئ (خطر على السلامة) يُنفَّذ فوراً بقرار الصيانة أو الأمن والسلامة أو المنشأة، ثم تُستكمل خطوات التصنيف والتقييم والاعتماد والإشعار خلال 24 ساعة. أي تمديد للمدة يُبلَّغ للمنشأة قبل انتهاء المدة المعلنة ويُعتمد بمستوى الإغلاق نفسه (R-11).', sort=201, updated_at=now() where code='F-01';
  update public.gov_processes set title='الجولات الميدانية وتفتيش بيئة الرعاية', owner='FAC', units='["FAC", "SAF", "MNT", "GEN", "BEN", "BME", "DIR"]'::jsonb, goal='اكتشاف المخاطر والعيوب قبل أن تصبح أعطالاً أو حوادث أو ملاحظات اعتماد، بجولات دورية موثقة لكل منشأة.', trigger='جدول الجولات السنوي (شهري للمناطق الحرجة، ربع سنوي لغيرها).', inputs='قائمة فحص الجولة الموحدة، ملاحظات الجولة السابقة.', outputs='تقرير جولة، بلاغات صيانة، ملاحظات بمسؤول ومهلة لكل منها.', kpi='تنفيذ الجولات المجدولة ≥ 95٪؛ إغلاق الملاحظات في مهلتها ≥ 85٪؛ انخفاض الملاحظات المتكررة.', steps='[{"unit": "FAC", "action": "إعداد جدول الجولات السنوي بالتنسيق مع الأمن والسلامة: المناطق الحرجة شهرياً وبقية المناطق ربع سنوياً", "sla": "بداية السنة", "where": "خطة الجولات", "kind": "step"}, {"unit": "FAC", "action": "تنفيذ الجولة بفريق مشترك (المرافق، الأمن والسلامة، الصيانة، مكافحة العدوى، الخدمات العامة) بقائمة فحص موحدة: الكهرباء، الأسقف والجدران والأرضيات، التسربات، النظافة، اللوحات الإرشادية", "sla": "حسب الجدول", "where": "قائمة فحص الجولة", "kind": "step"}, {"unit": "SAF", "action": "فحص بنود السلامة والأمن في الجولة: المخارج والممرات، الطفايات وأبواب الحريق، المواد الخطرة، الكاميرات والأبواب المقيدة", "sla": "حسب الجدول", "where": "قائمة فحص الجولة", "kind": "step"}, {"unit": "FAC", "action": "تصنيف كل ملاحظة: إصلاح فوري، بلاغ صيانة (G-05)، مشروع (G-02)، ملاحظة أمن وسلامة، أو مسؤولية المنشأة أو الخدمات العامة", "sla": "يوم", "where": "تقرير الجولة", "kind": "decision"}, {"unit": "MNT", "action": "تنفيذ الإصلاحات المحالة", "sla": "حسب الأولوية (R-17)", "where": "أوامر العمل", "kind": "step"}, {"unit": "SAF", "action": "معالجة ملاحظات الأمن والسلامة ومتابعتها مع الجهات المسؤولة", "sla": "حسب الخطورة", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "معالجة ملاحظات النظافة والإشغالات والمخلفات", "sla": "3 أيام", "where": "طلبات الخدمات", "kind": "step"}, {"unit": "BEN", "action": "معالجة ملاحظات التشغيل (تخزين في الممرات، أجهزة تسد المخارج، أبواب حريق مفتوحة)", "sla": "3 أيام", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "متابعة الإغلاق والتحقق من المعالجة في الجولة التالية", "sla": "الجولة التالية", "where": "تقرير الجولة", "kind": "step"}, {"unit": "DIR", "action": "مراجعة مؤشرات الجولات والملاحظات الأكثر تكراراً", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb, notes='نتائج الجولات مدخل رئيسي لتقييم مقاول التشغيل والصيانة (M-04) ولخطة إدارة المرافق السنوية (F-04).', sort=202, updated_at=now() where code='F-02';
  update public.gov_processes set title='سجل المواقع والأصول وحالة الغرف', owner='FAC', units='["FAC", "MNT", "BME", "PRJ", "IT", "SAF"]'::jsonb, goal='أن يكون لكل منشأة ومبنى ودور وغرفة وأصل رقم ثابت وحالة محدّثة، يُربط به كل بلاغ وأمر عمل وإغلاق وحادث ومشروع، فيُبنى تاريخ كامل لكل مكان.', trigger='الحصر الأولي، استلام مشروع، تغيير في المساحات، إضافة أصل أو إخراجه من الخدمة.', inputs='المخططات المعتمدة، بطاقات الأصول، محاضر الاستلام.', outputs='سجل محدّث، ملصقات ترميز (QR)، مخططات As-built محدّثة.', kpi='نسبة البلاغات المربوطة برقم غرفة أو أصل ≥ 95٪؛ تحديث السجل خلال أسبوع من أي تغيير.', steps='[{"unit": "FAC", "action": "اعتماد معيار الترميز: منشأة ـ مبنى ـ دور ـ غرفة (مثال KFH-ER-GF-021)، والتصنيف الهرمي للأصول", "sla": "مرة واحدة", "where": "معيار الترميز", "kind": "step"}, {"unit": "FAC", "action": "الحصر الميداني لكل منشأة وإصدار ملصقات الغرف والأصول الرئيسية", "sla": "حسب خطة الحصر", "where": "سجل المساحات", "kind": "step"}, {"unit": "FAC", "action": "تسجيل حالة كل غرفة: تشغيلية، مغلقة للصيانة، مغلقة مؤقتاً، خارج الخدمة، تحت التطوير", "sla": "لحظي", "where": "سجل المساحات", "kind": "step"}, {"unit": "MNT", "action": "تسجيل أصول المرافق (مولدات، مضخات، وحدات تكييف، لوحات كهرباء، مصاعد) ببياناتها وجدول صيانتها الوقائية", "sla": "أسبوع من الاستلام", "where": "سجل الأصول", "kind": "step"}, {"unit": "SAF", "action": "تسجيل أصول السلامة والأمن (لوحات الإنذار، الطفايات، الكاميرات، أنظمة الدخول) ومواقعها على السجل", "sla": "أسبوع من الاستلام", "where": "سجل الأصول", "kind": "step"}, {"unit": "BME", "action": "ربط الأجهزة الطبية في نظامها برقم الغرفة", "sla": "أسبوع", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "PRJ", "action": "تسليم مخططات As-built وقوائم الأصول الجديدة مع كل مشروع (G-04)", "sla": "عند الاستلام", "where": "المستندات", "kind": "step"}, {"unit": "FAC", "action": "تحديث السجل والمخططات عند أي تغيير (G-12، F-01)", "sla": "أسبوع", "where": "سجل المساحات", "kind": "step"}, {"unit": "FAC", "action": "مراجعة سنوية لدقة السجل بعينة ميدانية", "sla": "سنوياً", "where": "—", "kind": "decision"}]'::jsonb, notes='', sort=203, updated_at=now() where code='F-03';
  update public.gov_processes set title='خطة إدارة المرافق السنوية وتقييمها', owner='FAC', units='["FAC", "SAF", "MNT", "GEN", "BME", "PRJ", "DIR", "EXEC"]'::jsonb, goal='خطة سنوية مكتوبة لإدارة المرافق والسلامة بأهداف ومؤشرات ومسؤوليات، تُقيَّم وتُحسَّن كل عام، وتكون المرجع أمام متطلبات الاعتماد.', trigger='دورة التخطيط السنوية.', inputs='تقييم مخاطر المرافق، مؤشرات العام السابق، ملاحظات الجولات والاعتماد والدفاع المدني، تقارير الحوادث.', outputs='خطة معتمدة، سجل مخاطر، ميزانية، تقرير تقييم سنوي.', kpi='اعتماد الخطة قبل بداية السنة؛ تحقيق ≥ 80٪ من أهدافها.', steps='[{"unit": "FAC", "action": "تقييم مخاطر المرافق لكل منشأة (الاحتمالية × الأثر): السلامة الإنشائية، المرافق الحيوية، المساحات", "sla": "أكتوبر", "where": "سجل المخاطر", "kind": "step"}, {"unit": "SAF", "action": "مدخلات الأمن والسلامة: تحليل مخاطر الطوارئ، السلامة من الحريق، المواد الخطرة، الأمن، الحوادث وتحليلها (H-02، H-03، H-04، H-05، H-06)", "sla": "نوفمبر", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "مدخلات الصيانة الوقائية والاختبارات والاستبدال (G-06، M-03)", "sla": "نوفمبر", "where": "—", "kind": "step"}, {"unit": "PRJ", "action": "مدخلات المشاريع المخططة وأثرها على المساحات والتشغيل", "sla": "نوفمبر", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "إعداد الخطة: البرامج، المسؤوليات، المؤشرات، التدريب والتمارين، بالتنسيق مع الأمن والسلامة والصيانة والخدمات العامة والصيانة الطبية", "sla": "نوفمبر", "where": "خطة إدارة المرافق", "kind": "step"}, {"unit": "DIR", "action": "مراجعة الخطة والميزانية", "sla": "ديسمبر", "where": "—", "kind": "decision"}, {"unit": "EXEC", "action": "اعتماد الخطة السنوية", "sla": "ديسمبر", "where": "—", "kind": "decision"}, {"unit": "FAC", "action": "تقرير مؤشرات ربع سنوي لمدير الإدارة يتضمن مؤشرات الأمن والسلامة", "sla": "ربع سنوي", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "التقييم السنوي: ما تحقق، الفجوات، والتحسينات للعام التالي", "sla": "نهاية السنة", "where": "تقرير التقييم", "kind": "step"}]'::jsonb, notes='تُطابَق بنود الخطة مع معايير إدارة المرافق والسلامة المعتمدة لدى إدارة الجودة (سباهي) واشتراطات الدفاع المدني.', sort=204, updated_at=now() where code='F-04';
  update public.gov_processes set title='تصريح العمل والعزل الآمن', owner='MNT', units='["MNT", "SAF", "BEN", "FAC", "PRJ"]'::jsonb, goal='ألا تُنفَّذ أعمال عالية الخطورة إلا بتصريح مكتوب يحدد المخاطر والضوابط والمسؤول، مع عزل آمن لمصادر الطاقة.', trigger='أي عمل مذكور في R-13 من الصيانة أو مقاوليها أو مقاولي المشاريع.', inputs='وصف العمل والموقع والمدة، المنفذون ومؤهلاتهم، تقييم المخاطر، خطة العزل.', outputs='تصريح موقّع معلّق في الموقع، سجل العزل والأقفال، تصريح مغلق بعد إعادة الوضع.', kpi='100٪ من الأعمال عالية الخطورة بتصريح؛ صفر حوادث مرتبطة بالعزل؛ إغلاق التصاريح في يومها ≥ 95٪.', steps='[{"unit": "MNT", "action": "طلب التصريح: نوع العمل، الموقع، المدة، المنفذون، المعدات", "sla": "قبل 24 ساعة", "where": "نموذج تصريح العمل", "kind": "step", "role": "المنفذ أو المقاول"}, {"unit": "MNT", "action": "مراجعة تقييم المخاطر والضوابط: طفايات، مراقب حريق، تهوية، حماية من السقوط، معدات الوقاية", "sla": "4 ساعات", "where": "نموذج تصريح العمل", "kind": "decision", "role": "مُصدر التصاريح"}, {"unit": "SAF", "action": "اعتماد السلامة للتصاريح عالية الخطورة (الأعمال الحارة، الأماكن المحصورة، تعطيل أنظمة الحريق H-01)، والتحقق من تهيئة السلامة للعمالة (H-07)", "sla": "قبل البدء", "where": "نموذج تصريح العمل", "kind": "decision"}, {"unit": "BEN", "action": "موافقة مكافحة العدوى عند العمل في منطقة مشغّلة أو حرجة", "sla": "قبل البدء", "where": "—", "kind": "step", "role": "مكافحة العدوى"}, {"unit": "PRJ", "action": "مقاولو المشاريع يطبّقون النظام نفسه، ويتولى مهندس المشروع التنسيق مع مُصدر التصاريح", "sla": "قبل البدء", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "عزل مصادر الطاقة بالأقفال والبطاقات والتحقق من انعدام الجهد أو الضغط قبل البدء", "sla": "قبل البدء", "where": "سجل العزل", "kind": "step"}, {"unit": "MNT", "action": "التنفيذ مع إبقاء التصريح في الموقع، والتوقف فوراً عند تغيّر الظروف", "sla": "مدة التصريح", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "تفتيش مفاجئ على مواقع التصاريح، وإيقاف العمل فوراً عند خطر وشيك أو مخالفة", "sla": "أثناء التنفيذ", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "مراقبة الحريق في الأعمال الحارة حتى 30 دقيقة بعد الانتهاء", "sla": "بعد الانتهاء", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "إزالة الأقفال بعد التحقق من خلو الموقع، وإعادة التشغيل والاختبار", "sla": "فور الانتهاء", "where": "سجل العزل", "kind": "step"}, {"unit": "MNT", "action": "إغلاق التصريح بتوقيع المنفذ والمُصدر وأرشفته", "sla": "نفس اليوم", "where": "سجل التصاريح", "kind": "step", "role": "مُصدر التصاريح"}]'::jsonb, notes='التصريح صالح لوردية واحدة ويُجدَّد يومياً للأعمال الممتدة. لا تُزال بطاقة عزل إلا من واضعها أو بإجراء موثق يعتمده رئيس قسم الصيانة.', sort=301, updated_at=now() where code='M-01';
  update public.gov_processes set title='الإيقاف المخطط للمرافق الحيوية', owner='MNT', units='["MNT", "FAC", "DIR", "BEN", "BME", "IT", "SAF"]'::jsonb, goal='أي إيقاف مخطط للكهرباء أو المياه أو التكييف أو الغازات الطبية أو الشبكات يُنفَّذ بإشعار كافٍ وبديل جاهز واستعادة مختبرة دون أثر على المرضى.', trigger='صيانة أو ربط أو أعمال مشروع تتطلب فصل مرفق حيوي عن منطقة مشغولة.', inputs='المرفق والمناطق والغرف المتأثرة، الموعد والمدة، خطوات الإيقاف والاستعادة.', outputs='إشعار إيقاف معتمد، بدائل مجهزة، تقرير الاستعادة.', kpi='الإشعار في مهلته 100٪؛ الالتزام بمدة الإيقاف ≥ 95٪؛ صفر أثر سريري.', steps='[{"unit": "MNT", "action": "إعداد خطة الإيقاف: المرفق، المناطق المتأثرة، الموعد (خارج الذروة ما أمكن)، المدة، خطوات الإيقاف والاستعادة، وخطة الطوارئ إن طال الإيقاف", "sla": "7 أيام للحرجة؛ 72 ساعة لغيرها (R-15)", "where": "خطة الإيقاف", "kind": "step"}, {"unit": "FAC", "action": "مراجعة الأثر والتعارض مع الأعمال والإغلاقات الأخرى، وتأكيد الموعد", "sla": "يومان", "where": "سجل المساحات", "kind": "step"}, {"unit": "DIR", "action": "اعتماد الإيقاف في المناطق الحرجة", "sla": "يوم عمل", "where": "—", "kind": "decision"}, {"unit": "BEN", "action": "تأكيد الموعد وتجهيز البدائل: أسطوانات أكسجين، تأجيل الإجراءات غير العاجلة، تخزين مياه، إبلاغ الطاقم", "sla": "قبل 48 ساعة", "where": "—", "kind": "step", "role": "مدير المنشأة / التمريض"}, {"unit": "BME", "action": "تحديد الأجهزة الطبية الحرجة المتأثرة وتأمين بديلها أو مصدر طاقتها", "sla": "قبل 48 ساعة", "where": "سجل الأجهزة", "kind": "step"}, {"unit": "IT", "action": "حماية الخوادم والأنظمة (UPS، إيقاف آمن)", "sla": "قبل الإيقاف", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "تقييم أثر الإيقاف على أنظمة الحريق والإنذار والأبواب الإلكترونية، وتواجد الأمن في المناطق المتأثرة وتنظيم الحركة", "sla": "وقت الإيقاف", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "التنفيذ بتصريح عمل (M-01) مع فريق استعادة جاهز في الموقع", "sla": "الموعد المعتمد", "where": "أمر العمل", "kind": "step"}, {"unit": "MNT", "action": "الاستعادة والتحقق من عودة المرفق في كل منطقة: القراءات، إنذارات الغازات، درجات الحرارة", "sla": "فور الانتهاء", "where": "تقرير الإيقاف", "kind": "decision"}, {"unit": "FAC", "action": "إبلاغ المنشأة بالاستعادة وأرشفة تقرير الإيقاف", "sla": "نفس اليوم", "where": "—", "kind": "step"}]'::jsonb, notes='الإيقاف غير المخطط يُعامل طوارئ (G-11).', sort=302, updated_at=now() where code='M-02';
  update public.gov_processes set title='الاختبارات الدورية للأنظمة الحرجة', owner='MNT', units='["MNT", "SAF", "FAC", "BME", "BEN", "DIR"]'::jsonb, goal='التأكد بالاختبار الموثق أن الأنظمة التي يعتمد عليها المرضى تعمل عند الحاجة.', trigger='جدول الاختبارات السنوي.', inputs='قائمة الأنظمة الحرجة، توصيات الصانع، الاشتراطات.', outputs='سجلات اختبار موقّعة، إجراءات تصحيحية للنتائج خارج الحدود.', kpi='إنجاز الاختبارات في موعدها 100٪؛ إغلاق الإخفاقات خلال المهلة.', steps='[{"unit": "MNT", "action": "إعداد جدول الاختبارات: المولدات ومفاتيح تحويل الأحمال تحت حمل شهرياً، مضخات وأنظمة الحريق، إنذارات الغازات الطبية وضغوطها، المصاعد، التكييف والضغط في العمليات والعزل، UPS، خزانات المياه وجودتها", "sla": "بداية السنة", "where": "جدول الاختبارات", "kind": "step"}, {"unit": "FAC", "action": "تنسيق مواعيد الاختبارات المؤثرة على التشغيل مع المنشآت", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تنفيذ الاختبار وتسجيل القراءات (زمن التحويل، الحمل، الضغوط، درجات الحرارة)", "sla": "حسب الجدول", "where": "سجل الاختبارات", "kind": "step"}, {"unit": "SAF", "action": "حضور اختبارات أنظمة الإنذار والإطفاء ومضخات الحريق وتوثيقها في سجل الدفاع المدني (H-06)", "sla": "حسب الجدول", "where": "سجل السلامة", "kind": "step"}, {"unit": "MNT", "action": "أي نتيجة خارج الحدود: إصلاح فوري، أو طوارئ (G-11) إن مسّت السلامة، وتعطيل نظام حريق يُدار وفق H-01", "sla": "فوري", "where": "أمر العمل", "kind": "decision"}, {"unit": "BME", "action": "اختبارات الأجهزة الطبية الداعمة للحياة وفق جدولها", "sla": "حسب الجدول", "where": "نظام الأجهزة", "kind": "step"}, {"unit": "SAF", "action": "تمارين الإخلاء والإنذار بمشاركة المنشأة (H-02)", "sla": "حسب جدول التمارين", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "مراجعة ملخص الاختبارات والإخفاقات", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb, notes='الدوريات المذكورة مقترحة وتُضبط وفق توصيات الصانع والاشتراطات المعتمدة.', sort=303, updated_at=now() where code='M-03';
  update public.gov_processes set title='إدارة عقود التشغيل والصيانة وتقييم المقاولين', owner='MNT', units='["MNT", "FAC", "SAF", "DIR", "FIN", "PROC"]'::jsonb, goal='أن يُدفع لمقاول التشغيل والصيانة مقابل أداء مقاس، وأن تُطبَّق الحسومات والغرامات وفق العقد.', trigger='بدء عقد تشغيل وصيانة، ونهاية كل شهر.', inputs='العقد ونطاقه ومؤشراته، سجل البلاغات وأوامر العمل، خطة الصيانة الوقائية، كشف العمالة.', outputs='تقييم شهري، محضر حسومات، مستخلص معتمد، توصية التجديد أو الإنهاء.', kpi='تقييم شهري في موعده 100٪؛ العمالة الفعلية إلى التعاقدية ≥ 95٪.', steps='[{"unit": "MNT", "action": "استلام العقد: النطاق، المؤشرات (زمن الاستجابة، إنجاز الوقائية، العمالة، قطع الغيار)، الحسومات، وتعريف المقاول بالمنشآت والإجراءات", "sla": "بدء العقد", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "تهيئة السلامة لعمالة المقاول وإصدار بطاقات الدخول (H-07، H-05)", "sla": "قبل بدء العمل", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "متابعة يومية للحضور والعمالة وأوامر العمل والتزام المهل", "sla": "يومياً", "where": "أوامر العمل", "kind": "step"}, {"unit": "FAC", "action": "تقييم رضا المنشآت ونتائج الجولات (F-02) كمدخل للتقييم", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "مخالفات السلامة وحوادث عمالة المقاول خلال الشهر كمدخل للتقييم", "sla": "شهرياً", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "التقييم الشهري للأداء وحساب الحسومات وفق العقد", "sla": "خلال 5 أيام من نهاية الشهر", "where": "نموذج التقييم", "kind": "decision"}, {"unit": "DIR", "action": "اعتماد التقييم والحسومات", "sla": "3 أيام", "where": "—", "kind": "decision"}, {"unit": "FIN", "action": "صرف المستخلص بعد الحسومات", "sla": "حسب الدورة المالية", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تقرير أداء ربع سنوي، وتوصية قبل انتهاء العقد: تجديد، تعديل نطاق، أو إعادة طرح", "sla": "قبل الانتهاء بـ 6 أشهر", "where": "—", "kind": "decision"}, {"unit": "PROC", "action": "إجراءات التمديد أو إعادة الطرح", "sla": "حسب النظام", "where": "—", "kind": "step"}]'::j