  update public.gov_processes set title='قطع الغيار والمخزون الاحتياطي للأنظمة الحرجة', owner='MNT', units='["MNT", "DIR", "PROC", "FIN"]'::jsonb, goal='ألا يطول توقف نظام حرج بسبب انتظار قطعة غيار.', trigger='إعداد قائمة المخزون الاحتياطي، أو استهلاك قطعة دون الحد الأدنى.', inputs='قائمة الأنظمة الحرجة، معدلات الاستهلاك، مدد التوريد.', outputs='قائمة مخزون بحدود دنيا، طلبات تعويض، سجل استهلاك.', kpi='توفر القطع الحرجة ≥ 95٪؛ صفر توقف طويل بسبب نقص قطعة مدرجة.', steps='[{"unit": "MNT", "action": "تحديد القطع الحرجة لكل نظام (مولدات، مضخات، ضواغط تكييف، لوحات، مصاعد، مكونات أنظمة الحريق) وحدها الأدنى بحسب الاستهلاك ومدة التوريد", "sla": "سنوياً", "where": "قائمة المخزون", "kind": "step"}, {"unit": "DIR", "action": "اعتماد القائمة وميزانيتها", "sla": "مع خطة الصيانة", "where": "—", "kind": "decision"}, {"unit": "MNT", "action": "تسجيل كل صرف على أمر عمل ورقم أصل", "sla": "عند الصرف", "where": "سجل المخزون", "kind": "step"}, {"unit": "MNT", "action": "طلب التعويض عند بلوغ الحد الأدنى", "sla": "فوري", "where": "—", "kind": "decision"}, {"unit": "PROC", "action": "الشراء أو التوريد وفق العقد", "sla": "حسب مدة التوريد", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "جرد ربع سنوي ومراجعة القطع الراكدة", "sla": "ربع سنوي", "where": "سجل المخزون", "kind": "step"}]'::jsonb, notes='إن كان العقد يُلزم المقاول بتوفير القطع، تُطابق القائمة مع التزامه وتُراقب ضمن M-04.', sort=305, updated_at=now() where code='M-05';
  update public.gov_processes set title='تعطيل أنظمة السلامة من الحريق وإجراءات السلامة البديلة', owner='SAF', units='["SAF", "MNT", "FAC", "BEN", "DIR"]'::jsonb, goal='ألا تبقى منطقة مشغولة دون حماية من الحريق إلا بإجراءات بديلة معلنة ومراقبة حتى عودة النظام.', trigger='تعطيل مخطط أو عطل في الإنذار أو الرشاشات أو مضخات الحريق أو أبواب الحريق أو مخارج الطوارئ وممراتها.', inputs='النظام المتعطل والمنطقة المتأثرة، السبب، المدة المتوقعة.', outputs='سجل تعطيل، إجراءات بديلة مطبقة، إبلاغ الجهات المعنية، سجل إعادة التشغيل والاختبار.', kpi='صفر تعطيل غير مسجل؛ عودة النظام خلال المدة المعلنة ≥ 95٪.', steps='[{"unit": "MNT", "action": "إبلاغ الأمن والسلامة فوراً بأي عطل في أنظمة الحريق، أو بخطة التعطيل المخطط ومدتها", "sla": "فوري؛ 48 ساعة للمخطط", "where": "سجل التعطيل", "kind": "step"}, {"unit": "SAF", "action": "تسجيل التعطيل وتقييم الأثر: إذا تجاوز 4 ساعات خلال 24 ساعة تُفعَّل إجراءات السلامة البديلة (R-14)", "sla": "ساعة", "where": "سجل التعطيل", "kind": "decision"}, {"unit": "SAF", "action": "إبلاغ إدارة المنشأة والأقسام المتأثرة والمرافق، والدفاع المدني وفق الاشتراطات", "sla": "ساعة", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "دوريات مراقبة حريق للمنطقة، وتوفير طفايات إضافية، وإبقاء المخارج والممرات خالية، ومنع الأعمال الحارة", "sla": "طوال التعطيل", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "توعية العاملين في المنطقة وتقليل مصادر الاشتعال", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "الإصلاح أو إنهاء الأعمال، ثم اختبار النظام وإعادة ربطه بلوحة الإنذار", "sla": "بأسرع وقت", "where": "أمر العمل", "kind": "step"}, {"unit": "SAF", "action": "التحقق من الاختبار، وإنهاء الإجراءات البديلة، وإبلاغ الجهات بعودة النظام، وإغلاق السجل", "sla": "فور الاختبار", "where": "سجل التعطيل", "kind": "step"}, {"unit": "FAC", "action": "تحديث حالة المساحة في السجل إن تأثرت (F-03)", "sla": "نفس اليوم", "where": "سجل المساحات", "kind": "step"}, {"unit": "DIR", "action": "مراجعة سجل التعطيلات وتكرارها، وتوجيه الإجراءات التصحيحية أو ال