  update public.gov_rules set title='لا إغلاق بلا إشعار، ولا فتح بلا محضر', theme='إدارة المرافق', statement='لا تُغلق غرفة أو عيادة أو منطقة تشغيلية إلا بإشعار من المرافق وبديل متفق عليه مع المنشأة، ولا تعود للخدمة إلا بمحضر إعادة فتح وإجازة مكافحة العدوى.', criteria='["إشعار قبل 48 ساعة للإغلاق المخطط", "لوحة «مغلق للصيانة» بتاريخ العودة المتوقع", "حالة الغرفة محدّثة في السجل عند الإغلاق والفتح", "محضر إعادة فتح موقّع من المرافق والصيانة والأمن والسلامة والمنشأة", "أي تمديد يُبلَّغ قبل انتهاء المدة المعلنة"]'::jsonb, owner='FAC', process_code='F-01', note='الإغلاق الطارئ يُنفَّذ فوراً ويُستكمل توثيقه خلال 24 ساعة.' where code='R-11';
