  update public.gov_rules set title='تصريح العمل إلزامي للأعمال عالية الخطورة', theme='إدارة المرافق', statement='لا يبدأ عمل عالي الخطورة دون تصريح عمل ساري وعزل آمن، ويسري ذلك على الصيانة ومقاوليها ومقاولي المشاريع.', criteria='["الأعمال الحارة: لحام، قطع، تجليخ", "الأعمال الكهربائية التي تتطلب عزلاً أو قرب دوائر حية", "العمل على ارتفاع أكثر من مترين أو على الأسطح", "الأماكن المحصورة: خزانات، غرف تفتيش، مجاري هواء", "فتح الأسقف المستعارة في المناطق الحرجة", "أعمال الغازات الطبية", "أي تعطيل لأنظمة الحريق (H-01)"]'::jsonb, owner='MNT', process_code='M-01', note='الأمن والسلامة يعتمد التصاريح عالية الخطورة ويفتش عليها.' where code='R-13';
  update public.gov_rules set title='تعطيل أنظمة الحريق يستلزم إجراءات بديلة', theme='الأمن والسلامة', statement='أي تعطيل لنظام إنذار أو إطفاء أو باب حريق أو مخرج يُسجَّل فوراً لدى الأمن والسلامة، وإذا تجاوز 4 ساعات خلال 24 ساعة تُطبَّق إجراءات السلامة البديلة ويُبلَّغ الدفاع المدني وفق الاشتراطات.', criteria='["سجل تعطيل لكل حالة", "مراقبة حريق مستمرة للمنطقة", "طفايات إضافية ومخارج خالية", "منع الأعمال الحارة في المنطقة", "اختبار النظام قبل إنهاء الإجراءات البديلة"]'::jsonb, owner='SAF', process_code='H-01', note='المدة مقترحة وتُطابق مع اشتراطات الدفاع المدني.' where code='R-14';
