  update public.gov_activities set raci='{"MNT": "R", "SAF": "V", "PRJ": "C", "FAC": "I"}'::jsonb where scope='units' and title='إصدار تصاريح العمل والعزل الآمن (M-01)';
  update public.gov_activities set raci='{"SAF": "A", "MNT": "R", "FAC": "I", "DIR": "I"}'::jsonb where scope='units' and title='تعطيل أنظمة الحريق وإجراءات السلامة البديلة (H-01)';
  update public.gov_activities set raci='{"MNT": "R", "FAC": "V", "DIR": "A", "BME": "C", "IT": "C", "SAF": "C"}'::jsonb where scope='units' and title='الإيقاف المخطط للمرافق الحيوية (M-02)';
  update public.gov_activities set raci='{"FAC": "R", "SAF": "R", "MNT": "C", "GEN": "C", "BME": "C", "DIR": "I"}'::jsonb where scope='units' and title='الجولات الميدانية لبيئة الرعاية (F-02)';
  update public.gov_activities set raci='{"FAC": "R", "MNT": "C", "SAF": "C", "BME": "C", "PRJ": "C", "IT": "C"}'::jsonb where scope='units' and title='سجل المواقع والأصول وحالة الغرف (F-03)';
  update public.gov_activities set raci='{"MNT": "R", "BME": "R", "SAF": "V", "FAC": "V", "DIR": "I"}'::jsonb where scope='units' and title='الاختبارات الدورية للأنظمة الحرجة (M-03)';
  update public.gov_activities set raci='{"MNT": "R", "FAC": "C", "SAF": "C", "DIR": "A"}'::jsonb where scope='units' and title='تقييم مقاولي التشغيل والصيانة الشهري (M-04)';
  update public.gov_activities set raci='{"FAC": "R", "SAF": "R", "MNT": "C", "GEN": "C", "BME": "C", "PRJ": "C", "DIR": "V", "EXEC": "A"}'::jsonb where scope='units' and title='خطة إدارة المرافق السنوية وتقييمها (F-04)';
  update public.gov_faq set a='الإجراء F-01: ترفع الصيانة (أو مهندس المشروع) طلب إغلاق قبل 5 أيام عمل بأرقام الغرف والمدة، فتصنّفه المرافق وتحدد من يعتمده وفق R-12، وتتفق المنشأة على البديل، وتقيّم مكافحة العدوى فئة ICRA، ويقيّم الأمن والسلامة مسارات الإخلاء. ثم يصدر إشعار الإغلاق قبل 48 ساعة، وتُخلى الأجهزة والأثاث وتُركّب الحواجز ولوحة «مغلق للصيانة»، وتُحدَّث حالة الغرفة في السجل.', links='["F-01", "R-11", "R-12"]'::jsonb where q='كيف أغلق عيادة أو غرفة للصيانة؟';
  update public.gov_faq set a='بعد الاختبار والتنظيف النهائي وإجازة مكافحة العدوى، تُجرى جولة إعادة فتح مشتركة (المرافق والصيانة والأمن والسلامة والمنشأة) بقائمة فحص، ولا تعود الغرفة «تشغيلية» إلا بمحضر موقّع (R-11، R-23).', links='["F-01", "R-11", "R-23"]'::jsonb where q='كيف تعود الغرفة للخدمة بعد الصيانة؟';
  update public.gov_faq set a='في كل عمل عالي الخطورة: الأعمال الحارة، الكهرباء التي تتطلب عزلاً، الارتفاعات، الأماكن المحصورة، فتح الأسقف في المناطق الحرجة، الغازات الطبية، وتعطيل أنظمة الحريق (R-13). التصريح يصدر وفق M-01 مع عزل آمن بالأقفال والبطاقات، ويعتمد الأمن والسلامة التصاريح عالية الخطورة.', links='["M-01", "R-13"]'::jsonb where q='متى أحتاج تصريح عمل؟';
  update public.gov_faq set a='يُسجَّل التعطيل فوراً لدى الأمن والسلامة، وإذا تجاوز 4 ساعات خلال 24 ساعة تُطبَّق إجراءات السلامة البديلة: مراقبة حريق، طفايات إضافية، مخارج خالية، منع الأعمال الحارة، وإبلاغ الدفاع المدني (H-01، R-14).', links='["H-01", "R-14"]'::jsonb where q='ماذا نفعل إذا تعطّل الإنذار أو الرشاشات؟';
  update public.gov_faq set a='بخطة إيقاف وفق M-02 بإشعار 72 ساعة (7 أيام للمناطق الحرجة مع اعتماد مدير الإدارة)، وبدائل جاهزة قبل البدء، وفريق استعادة في الموقع، وتحقق من عودة المرفق في كل منطقة (R-15).', links='["M-02", "R-15"]'::jsonb where q='كيف نوقف الكهرباء أو المياه أو الأكسجين عن منطقة؟';
  update public.gov_faq set a='من سجل المواقع والأصول (F-03): لكل غرفة وأصل رقم ثابت وحالة (تشغيلية، مغلقة للصيانة، خارج الخدمة…)، وكل بلاغ أو إغلاق أو حادث يُربط برقمه (R-16).', links='["F-03", "R-16"]'::jsonb where q='كيف نعرف حالة كل غرفة وأصل؟';
  update public.gov_faq set a='بأثره لا بمن رفعه (R-17): طارئ خلال ساعتين، عاجل خلال 24 ساعة، عادي خلال 5 أيام عمل، ومخطط يُجدول مع الصيانة الوقائية.', links='["R-17", "G-05"]'::jsonb where q='كيف تُحدَّد أولوية بلاغ المرافق؟';
  update public.gov_faq set a='تقييم شهري خلال 5 أيام من نهاية الشهر وفق مؤشرات العقد (الاستجابة، الوقائية، العمالة، القطع) مع رضا المنشآت ونتائج الجولات ومخالفات السلامة، ثم حسومات يعتمدها مدير الإدارة قبل صرف المستخلص (M-04، R-18).', links='["M-04", "R-18"]'::jsonb where q='كيف يُقيَّم مقاول التشغيل والصيانة؟';
  update public.gov_router set opts='[{"t": "غرفة أو عيادة أو منطقة لأعمال صيانة أو تطوير", "out": {"proc": "F-01", "unit": "FAC", "title": "المرافق — إغلاق المساحات", "text": "طلب إغلاق قبل 5 أيام عمل بأرقام الغرف والمدة؛ المرافق تصنّفه وتتفق مع المنشأة على البديل، ولا تعود المساحة إلا بمحضر إعادة فتح."}}, {"t": "كهرباء أو مياه أو تكييف أو غازات طبية عن منطقة", "out": {"proc": "M-02", "unit": "MNT", "title": "الصيانة — الإيقاف المخطط", "text": "خطة إيقاف بإشعار 72 ساعة (7 أيام للمناطق الحرجة) مع بدائل جاهزة وفريق استعادة."}}, {"t": "نظام إنذار أو إطفاء أو باب أو مخرج حريق", "out": {"proc": "H-01", "unit": "SAF", "title": "الأمن والسلامة — تعطيل أنظمة الحريق", "text": "يُسجَّل فوراً لدى الأمن والسلامة، وإذا تجاوز 4 ساعات تُطبَّق إجراءات السلامة البديلة ويُبلَّغ الدفاع المدني."}}, {"t": "عمل خطر: لحام، كهرباء، ارتفاعات، أماكن محصورة", "out": {"proc": "M-01", "unit": "MNT", "title": "الصيانة — تصريح العمل", "text": "تصريح عمل قبل 24 ساعة يعتمده الأمن والسلامة للأعمال عالية الخطورة، وعزل آمن بالأقفال والبطاقات قبل البدء."}}]'::jsonb where key='close';
  update public.gov_handoffs set to_unit='SAF' where from_unit='MNT' and to_unit='FAC' and trigger='تعطل نظام حريق أو تعطيله';
  update public.gov_units set sort = sort + 1 where kind = 'ext';
  update public.gov_units set mission = replace(mission, 'النقل، الأمن والسلامة، إدارة النفايات', 'النقل، إدارة النفايات'), duties = duties - 'الأمن والسلامة وتنظيم الدخول لمواقع العمل' where code = 'GEN';
  update public.gov_units set duties = replace(duties::text, 'متابعة اشتراطات الدفاع المدني والسلامة الإنشائية للمباني', 'السلامة الإنشائية للمباني، ومعالجة ملاحظات الدفاع المدني المعمارية مع الأمن والسلامة')::jsonb where code = 'FAC';
  update public.gov_units set mission = replace(mission, 'بأقسامها السبعة', 'بأقسامها الثمانية') where code = 'DIR';
  update public.gov_units set duties = duties || '["المشاركة في خطط الطوارئ والاستمرارية واختبارات أنظمة الحريق مع الأمن والسلامة"]'::jsonb where code = 'MNT' and not duties::text like '%خطط الطوارئ والاستمرارية%';
  perform pg_temp.step_text('G-01', 'عطل قائم / احتياج جديد / جهاز طبي / تقني / خدمة عامة', 'عطل قائم / احتياج جديد / جهاز طبي / تقني / خدمة عامة / أمن وسلامة');
  perform pg_temp.step_after('G-01', 'خدمة عامة ← طلب خدمة', '{"unit": "SAF", "action": "أمن أو سلامة ← بلاغ حادث أو ملاحظة سلامة للأمن والسلامة (H-03)", "sla": "فوري للخطير", "where": "سجل الحوادث", "kind": "step"}'::jsonb);
  perform pg_temp.step_text('G-04', 'المرافق، الصيانة، تقنية المعلومات', 'المرافق، الصيانة، الأمن والسلامة، تقنية المعلومات');
  perform pg_temp.step_after('G-04', 'التأكد من جاهزية مواقع الأجهزة الطبية', '{"unit": "SAF", "action": "فحص السلامة من الحريق: المخارج، الإنذار والإطفاء، أبواب الحريق، اللوحات الإرشادية، واشتراطات الدفاع المدني قبل التشغيل (H-06، R-23)", "sla": "قبل المحضر", "where": "قائمة فحص السلامة", "kind": "decision"}'::jsonb);
  perform pg_temp.step_text('G-10', 'إبلاغ الخدمات العامة والمنشأة بخطة الأعمال', 'إبلاغ الخدمات العامة والأمن والسلامة والمنشأة بخطة الأعمال');
  perform pg_temp.step_text('G-10', 'تركيب الحواجز واللوحات التحذيرية وتنظيم الدخول والأمن', 'تركيب الحواجز واللوحات التحذيرية');
  perform pg_temp.step_after('G-10', 'تركيب الحواجز واللوحات التحذيرية', '{"unit": "SAF", "action": "خطة سلامة الموقع: مخارج الطوارئ والممرات البديلة، طفايات الموقع، تنظيم الدخول وبطاقات عمالة المقاول (H-05، H-07)، وتصاريح الأعمال الخطرة (M-01)", "sla": "قبل المباشرة", "where": "—", "kind": "step"}'::jsonb);
  perform pg_temp.step_after('G-10', 'النظافة الدورية وإدارة المخلفات', '{"unit": "SAF", "action": "تفتيش السلامة الدوري على الموقع وإيقاف العمل عند خطر وشيك (R-24)", "sla": "أسبوعياً", "where": "—", "kind": "step"}'::jsonb);
  perform pg_temp.step_unit('G-11', 'تأمين الموقع وتنظيم الإخلاء الجزئي', 'SAF');
  perform pg_temp.step_text('G-11', 'تأمين الموقع وتنظيم الإخلاء الجزئي إن لزم', 'تأمين الموقع وتفعيل رمز الطوارئ وتنظيم الإخلاء الجزئي إن لزم، والتواصل مع الدفاع المدني (H-02)');
  perform pg_temp.step_text('G-11', 'الاتصال المباشر بغرفة الصيانة/الأمن', 'الاتصال المباشر بغرفة الصيانة، أو بالأمن والسلامة في الحريق والحوادث الأمنية والإصابات');
  perform pg_temp.step_text('G-11', 'إبلاغ المرافق ومدير الإدارة', 'إبلاغ المرافق والأمن والسلامة ومدير الإدارة');
  perform pg_temp.step_after('G-11', 'تسجيل البلاغ لاحقاً وتقرير الواقعة', '{"unit": "SAF", "action": "تسجيل الحادث والتحقيق في أسبابه وتوصيات منع التكرار (H-03)", "sla": "5 أيام عمل", "where": "سجل الحوادث", "kind": "step"}'::jsonb);
  perform pg_temp.step_after('G-12', 'تقييم الملاءمة مع المخططات والاشتراطات', '{"unit": "SAF", "action": "مراجعة أثر التغيير على مخارج الطوارئ ومسارات الإخلاء وحمولة الإشغال وأنظمة الحريق، والحاجة لموافقة الدفاع المدني (H-06)", "sla": "3 أيام عمل", "where": "—", "kind": "decision"}'::jsonb);
  update public.gov_processes set units = units || '["SAF"]'::jsonb where code in ('G-01', 'G-04', 'G-10', 'G-11', 'G-12') and not units ? 'SAF';
  update public.gov_processes set units = units - 'GEN' where code = 'G-11' and not steps::text like '%"unit": "GEN"%';
  update public.gov_rules set criteria = replace(criteria::text, 'تبليغ المنشأة والأمن"', 'تبليغ المنشأة والأمن والسلامة"')::jsonb where code = 'R-06';
  update public.gov_rules set criteria = criteria || '["خطة سلامة الموقع وتهيئة عمالة المقاول من الأمن والسلامة"]'::jsonb where code = 'R-06' and not criteria::text like '%خطة سلامة الموقع%';
  update public.gov_rules set statement = replace(statement, 'يُتصل بالصيانة مباشرة', 'يُتصل بالصيانة مباشرة (وبالأمن والسلامة في الحريق والحوادث الأمنية والإصابات)') where code = 'R-09' and not statement like '%وبالأمن والسلامة%';
  update public.gov_rules set criteria = criteria || '["تحقيق الحادث وتوصياته (H-03)"]'::jsonb where code = 'R-09' and not criteria::text like '%H-03%';
  update public.gov_activities set raci = (raci) || '{"SAF": "C"}'::jsonb where scope='units' and title='الفصل في تعارض الاختصاص بين الأقسام' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "C"}'::jsonb where scope='units' and title='التصميم والمخططات ووثائق الطرح' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "R"}'::jsonb where scope='units' and title='الاستلام الابتدائي والتسليم للتشغيل' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "C"}'::jsonb where scope='units' and title='إدارة المساحات والانتقال وإعادة التوزيع' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci - 'GEN') || '{"SAF": "R"}'::jsonb where scope='units' and title='اشتراطات الدفاع المدني والسلامة الإنشائية للمباني' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "C"}'::jsonb where scope='units' and title='تهيئة المواقع قبل/بعد الأعمال (حواجز، نظافة، حركة)' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "C"}'::jsonb where scope='units' and title='الخطة السنوية والميزانية للمشاريع والصيانة' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "R"}'::jsonb where scope='units' and title='التقرير الشهري لمؤشرات الأقسام' and not raci ? 'SAF';
  update public.gov_activities set raci = (raci) || '{"SAF": "C"}'::jsonb where scope='units' and title='التصعيد إلى الإدارة التنفيذية' and not raci ? 'SAF';
  update public.gov_handoffs set trigger = replace(trigger, 'نقل، أمن، نفايات', 'نقل، نفايات') where trigger like '%نقل، أمن، نفايات%';
  update public.gov_faq set a = replace(a, 'الخدمات العامة تهيئ الموقع وتنظفه يومياً', 'الأمن والسلامة يضع خطة سلامة الموقع ويهيئ عمالة المقاول، والخدمات العامة تهيئ الموقع وتنظفه يومياً') where a like '%الخدمات العامة تهيئ الموقع وتنظفه يومياً%' and not a like '%خطة سلامة الموقع%';
  update public.gov_faq set a = replace(a, 'اتصال مباشر بغرفة الصيانة أو الأمن', 'اتصال مباشر بغرفة الصيانة أو بالأمن والسلامة'), links = links || '["H-03"]'::jsonb where a like '%اتصال مباشر بغرفة الصيانة أو الأمن،%';
  update public.gov_faq set a = replace(a, 'الخدمات العامة تؤمّن الموقع', 'الأمن والسلامة يؤمّن الموقع وينظم الإخلاء') where a like '%الخدمات العامة تؤمّن الموقع%';
  update public.gov_faq set a = replace(a, 'وتوزع الأعمال:', 'ويراجع الأمن والسلامة أثره على المخارج والإخلاء، وتوزع الأعمال:') where a like '%المرافق تقيّم الطلب مع المخططات%' and not a like '%يراجع الأمن والسلامة%';
  update public.gov_router set opts = replace(opts::text, 'نقل، أمن، نفايات', 'نقل، نفايات')::jsonb where key = 'start';
  delete from public.gov_activities a using public.gov_activities x where a.scope = x.scope and a.title = x.title and a.id > x.id;
  delete from public.gov_handoffs a using public.gov_handoffs x where a.from_unit = x.from_unit and a.to_unit = x.to_unit and a.trigger = x.trigger and a.id > x.id;
  delete from public.gov_faq a using public.gov_faq x where a.q = x.q and a.id > x.id;
end if;
end $$;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-01','تعطيل أنظمة السلامة من الحريق وإجراءات السلامة البديلة','SAF','["SAF", "MNT", "FAC", "BEN", "DIR"]'::jsonb,'ألا تبقى منطقة مشغولة دون حماية من الحريق إلا بإجراءات بديلة معلنة ومراقبة حتى عودة النظام.','تعطيل مخطط أو عطل في الإنذار أو الرشاشات أو مضخات الحريق أو أبواب الحريق أو مخارج الطوارئ وممراتها.','النظام المتعطل والمنطقة المتأثرة، السبب، المدة المتوقعة.','سجل تعطيل، إجراءات بديلة مطبقة، إبلاغ الجهات المعنية، سجل إعادة التشغيل والاختبار.','صفر تعطيل غير مسجل؛ عودة النظام خلال المدة المعلنة ≥ 95٪.','[{"unit": "MNT", "action": "إبلاغ الأمن والسلامة فوراً بأي عطل في أنظمة الحريق، أو بخطة التعطيل المخطط ومدتها", "sla": "فوري؛ 48 ساعة للمخطط", "where": "سجل التعطيل", "kind": "step"}, {"unit": "SAF", "action": "تسجيل التعطيل وتقييم الأثر: إذا تجاوز 4 ساعات خلال 24 ساعة تُفعَّل إجراءات السلامة البديلة (R-14)", "sla": "ساعة", "where": "سجل التعطيل", "kind": "decision"}, {"unit": "SAF", "action": "إبلاغ إدارة المنشأة والأقسام المتأثرة والمرافق، والدفاع المدني وفق الاشتراطات", "sla": "ساعة", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "دوريات مراقبة حريق للمنطقة، وتوفير طفايات إضافية، وإبقاء المخارج والممرات خالية، ومنع الأعمال الحارة", "sla": "طوال التعطيل", "where": "—", "kind": "step"}, {"unit": "BEN", "action": "توعية العاملين في المنطقة وتقليل مصادر الاشتعال", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "الإصلاح أو إنهاء الأعمال، ثم اختبار النظام وإعادة ربطه بلوحة الإنذار", "sla": "بأسرع وقت", "where": "أمر العمل", "kind": "step"}, {"unit": "SAF", "action": "التحقق من الاختبار، وإنهاء الإجراءات البديلة، وإبلاغ الجهات بعودة النظام، وإغلاق السجل", "sla": "فور الاختبار", "where": "سجل التعطيل", "kind": "step"}, {"unit": "FAC", "action": "تحديث حالة المساحة في السجل إن تأثرت (F-03)", "sla": "نفس اليوم", "where": "سجل المساحات", "kind": "step"}, {"unit": "DIR", "action": "مراجعة سجل التعطيلات وتكرارها، وتوجيه الإجراءات التصحيحية أو الاستبدال (G-02)", "sla": "شهرياً", "where": "—", "kind": "step"}]'::jsonb,'التعطيل غير المخطط الذي يهدد السلامة يُعامل طوارئ (G-11) بالتوازي مع هذا الإجراء.',401) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-02','خطط الطوارئ والإخلاء والتمارين','SAF','["SAF", "BEN", "MNT", "FAC", "GEN", "IT", "DIR"]'::jsonb,'أن تعرف كل منشأة ماذا تفعل في الحريق والإخلاء وانقطاع المرافق والحوادث الأمنية والانسكابات، وأن يُختبر ذلك بتمارين موثقة.','الدورة السنوية للخطة، أو حدث فعلي، أو تغيير كبير في المبنى أو التشغيل.','تحليل قابلية التعرض للمخاطر (HVA)، المخططات ومسارات الإخلاء، نتائج التمارين والحوادث السابقة.','خطة طوارئ معتمدة لكل منشأة، رموز طوارئ معممة، جدول تمارين وتقارير تقييمها.','تنفيذ التمارين المجدولة 100٪؛ إغلاق ملاحظات التمارين في مهلتها ≥ 90٪.','[{"unit": "SAF", "action": "تحليل قابلية التعرض للمخاطر (HVA) لكل منشأة بالتنسيق مع إدارتها", "sla": "سنوياً", "where": "سجل المخاطر", "kind": "step"}, {"unit": "SAF", "action": "إعداد خطة الطوارئ: رموز الطوارئ (حريق، إخلاء، انسكاب، تهديد أمني، انقطاع مرافق)، مسارات الإخلاء ونقاط التجمع، الأدوار وقوائم الاتصال", "sla": "سنوياً", "where": "خطة الطوارئ", "kind": "step"}, {"unit": "MNT", "action": "خطة استمرارية المرافق: المولدات والوقود، المياه، الغازات الطبية، والاستجابة لانقطاعها", "sla": "مع الخطة", "where": "—", "kind": "step"}, {"unit": "IT", "action": "خطة استمرارية الأنظمة والاتصالات أثناء الطوارئ", "sla": "مع الخطة", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "اعتماد الخطة", "sla": "قبل بداية السنة", "where": "—", "kind": "decision"}, {"unit": "BEN", "action": "تعميم الخطة وتدريب الطاقم على الرموز والأدوار", "sla": "خلال شهر من الاعتماد", "where": "—", "kind": "step", "role": "مدير المنشأة"}, {"unit": "SAF", "action": "جدولة التمارين وتنفيذها: تمرين حريق لكل منشأة ربع سنوياً، وتمرين إخلاء مرة سنوياً على الأقل", "sla": "حسب الجدول", "where": "جدول التمارين", "kind": "step"}, {"unit": "SAF", "action": "تقييم كل تمرين: زمن الاستجابة، وصول الإنذار، الالتزام بالأدوار، الملاحظات", "sla": "3 أيام", "where": "تقرير التمرين", "kind": "decision"}, {"unit": "FAC", "action": "معالجة ملاحظات التمارين المتعلقة بالمبنى والمخارج واللوحات (G-05 أو G-02)", "sla": "حسب الأولوية", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "تحديث الخطة بعد كل حدث فعلي أو تمرين يكشف فجوة", "sla": "شهر", "where": "خطة الطوارئ", "kind": "step"}]'::jsonb,'الدوريات مقترحة وتُطابَق مع اشتراطات الدفاع المدني ومتطلبات الاعتماد.',402) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-03','الإبلاغ عن الحوادث والتحقيق فيها','SAF','["BEN", "SAF", "MNT", "FAC", "DIR"]'::jsonb,'أن يُبلَّغ عن كل حادث أو شبه حادث، ويُحقَّق في أسبابه، وتُنفَّذ إجراءات تمنع تكراره.','إصابة، حريق، سرقة أو اعتداء، انسكاب مواد خطرة، ضرر بالممتلكات، أو شبه حادث.','بلاغ الحادث، الصور، أقوال الشهود، الموقع ورقم الغرفة أو الأصل.','سجل حادث مصنّف، تقرير تحقيق بالسبب الجذري، إجراءات تصحيحية بمسؤول ومهلة.','الإبلاغ خلال 24 ساعة 100٪؛ إغلاق الإجراءات التصحيحية في مهلتها ≥ 85٪؛ انخفاض الحوادث المتكررة.','[{"unit": "BEN", "action": "الإبلاغ الفوري عن الحادث أو شبه الحادث مع الموقع ورقم الغرفة أو الأصل (R-19)", "sla": "خلال 24 ساعة؛ فوراً للخطير", "where": "نموذج بلاغ حادث", "kind": "step", "role": "أي موظف"}, {"unit": "SAF", "action": "استلام البلاغ وتصنيف خطورته (بسيط، متوسط، خطير)", "sla": "يوم", "where": "سجل الحوادث", "kind": "decision"}, {"unit": "SAF", "action": "الحوادث الخطيرة (إصابة بالغة، حريق، وفاة، اعتداء): إبلاغ مدير الإدارة فوراً والجهات المختصة", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "التحقيق: المعاينة، الشهود، الصور، وتحليل السبب الجذري", "sla": "5 أيام عمل", "where": "تقرير التحقيق", "kind": "step"}, {"unit": "MNT", "action": "الإجراءات التصحيحية الفنية: إصلاح (G-05) أو توصية مشروع (G-02)", "sla": "حسب الأولوية", "where": "أوامر العمل", "kind": "step"}, {"unit": "FAC", "action": "ربط الحادث بسجل الغرفة أو الأصل (F-03)", "sla": "أسبوع", "where": "سجل المساحات", "kind": "step"}, {"unit": "SAF", "action": "متابعة إغلاق الإجراءات التصحيحية وإبلاغ صاحب البلاغ بالنتيجة", "sla": "حسب المهل", "where": "سجل الحوادث", "kind": "step"}, {"unit": "DIR", "action": "مراجعة مؤشرات الحوادث الشهرية: العدد لكل منشأة، التكرار، زمن الإغلاق", "sla": "شهرياً", "where": "—", "kind": "step"}]'::jsonb,'الحدث الجاري (حريق، حادث أمني) يُعامل أولاً طوارئ (G-11)، ثم يُستكمل هذا الإجراء.',403) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-04','إدارة المواد الخطرة','SAF','["SAF", "BEN", "GEN", "MNT"]'::jsonb,'أن تكون كل مادة خطرة معروفة الموقع والكمية، مخزنة بأمان، مع بطاقة بيانات السلامة (SDS) ووسيلة احتواء الانسكاب.','دخول مادة خطرة جديدة، جرد سنوي، أو انسكاب.','قوائم المواد من الأقسام والمقاولين، بطاقات بيانات السلامة.','قائمة جرد لكل منشأة، مخازن مطابقة، سجلات تدريب، تقارير انسكاب.','اكتمال قائمة الجرد وبطاقات SDS 100٪؛ صفر انسكاب دون احتواء موثق.','[{"unit": "SAF", "action": "إعداد قائمة جرد المواد الخطرة لكل منشأة وقسم (كيميائيات المختبر، مواد التنظيف، الغازات، الوقود، الزيوت) مع بطاقة SDS لكل مادة", "sla": "سنوياً", "where": "سجل المواد الخطرة", "kind": "step"}, {"unit": "SAF", "action": "تقييم أماكن التخزين: الملصقات، التهوية، الفصل بين المواد غير المتوافقة، أطقم الانسكاب", "sla": "ربع سنوي", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "تخزين الوقود والغازات والزيوت في المحطات والمولدات وفق الاشتراطات", "sla": "مستمر", "where": "—", "kind": "step"}, {"unit": "GEN", "action": "التخلص من النفايات الخطرة عبر المقاول المرخص وتوثيق الشحنات", "sla": "حسب الجدول", "where": "سجل النفايات", "kind": "step"}, {"unit": "SAF", "action": "تدريب العاملين المتعاملين مع المواد الخطرة على التعامل والاحتواء", "sla": "سنوياً", "where": "سجل التدريب", "kind": "step"}, {"unit": "BEN", "action": "الإبلاغ الفوري عن أي انسكاب وتطبيق إجراء الاحتواء", "sla": "فوري", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "التحقيق في الانسكاب (H-03) وتحديث الضوابط", "sla": "5 أيام عمل", "where": "تقرير التحقيق", "kind": "decision"}]'::jsonb,'المواد المشعة تُدار وفق متطلبات الحماية الإشعاعية لدى المنشأة، ويُدرج موقعها في القائمة.',404) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-05','الأمن وضبط الدخول','SAF','["SAF", "IT", "MNT", "BEN", "DIR", "FIN"]'::jsonb,'حماية المرضى والزوار والعاملين والممتلكات بضبط الدخول للمناطق المقيدة، وحراسة ومراقبة فعالة، واستجابة سريعة للحوادث الأمنية.','بدء عقد الحراسات، تشغيل مبنى أو منطقة جديدة، أو دخول مقاول.','تصنيف المناطق، عقد الحراسات، أنظمة المراقبة والتحكم بالدخول.','خطة أمن لكل منشأة، سجل البطاقات والمفاتيح، تقييم شهري لمقاول الحراسة.','صفر دخول لمقاول بلا بطاقة؛ زمن الاستجابة للبلاغ الأمني ≤ 5 دقائق (مقترح)؛ جاهزية الكاميرات ≥ 95٪.','[{"unit": "SAF", "action": "تصنيف المناطق: عامة، مقيدة، حساسة (الصيدلية، الحضانة، غرف الخوادم والكهرباء، المستودعات)", "sla": "سنوياً", "where": "خطة الأمن", "kind": "step"}, {"unit": "SAF", "action": "توزيع الحراسات والدوريات وفق عقد الحراسة وخطة الأمن", "sla": "مستمر", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "إصدار بطاقات الدخول للعاملين والمقاولين بعد تهيئة السلامة (H-07)؛ مقاول بلا بطاقة لا يدخل (R-21)", "sla": "قبل بدء العمل", "where": "سجل البطاقات", "kind": "step"}, {"unit": "IT", "action": "تشغيل أنظمة المراقبة والتحكم بالدخول (البنية والشبكة والتسجيل)", "sla": "مستمر", "where": "—", "kind": "step"}, {"unit": "MNT", "action": "صيانة الأقفال والأبواب الأمنية والحواجز", "sla": "حسب البلاغ", "where": "أوامر العمل", "kind": "step"}, {"unit": "SAF", "action": "إدارة المفاتيح والأقفال الرئيسية بسجل استلام وتسليم", "sla": "مستمر", "where": "سجل المفاتيح", "kind": "step"}, {"unit": "SAF", "action": "الاستجابة للحوادث الأمنية وتوثيقها (H-03)", "sla": "فوري", "where": "سجل الحوادث", "kind": "step"}, {"unit": "SAF", "action": "التقييم الشهري لمقاول الحراسة وحساب الحسومات وفق العقد", "sla": "خلال 5 أيام من نهاية الشهر", "where": "نموذج التقييم", "kind": "decision"}, {"unit": "DIR", "action": "اعتماد التقييم والحسومات", "sla": "3 أيام", "where": "—", "kind": "decision"}, {"unit": "FIN", "action": "صرف مستخلص الحراسات بعد الحسومات", "sla": "حسب الدورة المالية", "where": "—", "kind": "step"}]'::jsonb,'',405) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-06','الامتثال لاشتراطات الدفاع المدني','SAF','["SAF", "MNT", "PRJ", "FAC", "DIR"]'::jsonb,'أن تبقى كل منشأة مرخصة ومطابقة لاشتراطات الدفاع المدني في أنظمة الحريق والمخارج والإشغال طوال الوقت.','مواعيد التراخيص، الفحوص الدورية، زيارات الدفاع المدني، تشغيل مساحة جديدة أو معدّلة.','تراخيص المنشآت، سجلات صيانة واختبار أنظمة الحريق، مخططات المشاريع.','سجل تراخيص محدّث، تقارير فحص، خطط معالجة ملاحظات الدفاع المدني.','صفر ترخيص منتهٍ؛ إغلاق ملاحظات الدفاع المدني في مهلتها 100٪.','[{"unit": "SAF", "action": "سجل تراخيص الدفاع المدني لكل منشأة ومواعيد تجديدها", "sla": "مستمر", "where": "سجل التراخيص", "kind": "step"}, {"unit": "MNT", "action": "صيانة أنظمة الإنذار والإطفاء واختبارها وفق الجدول (G-06، M-03) وتزويد سجل السلامة بالنتائج", "sla": "حسب الجدول", "where": "سجل الاختبارات", "kind": "step"}, {"unit": "SAF", "action": "الفحص الدوري: الطفايات، المخارج والممرات، أبواب الحريق، اللوحات الإرشادية، إنارة الطوارئ", "sla": "شهرياً", "where": "قائمة فحص السلامة", "kind": "step"}, {"unit": "PRJ", "action": "مراجعة مخططات المشاريع لاشتراطات الحريق قبل الطرح، والحصول على موافقة الدفاع المدني حيث يلزم", "sla": "قبل الطرح", "where": "المستندات", "kind": "step"}, {"unit": "SAF", "action": "فحص السلامة من الحريق قبل تشغيل أي مساحة جديدة أو معدّلة (G-04، R-23)", "sla": "قبل التشغيل", "where": "—", "kind": "decision"}, {"unit": "SAF", "action": "مرافقة زيارات الدفاع المدني، وإعداد خطة معالجة الملاحظات بمسؤول ومهلة", "sla": "خلال أسبوع من الزيارة", "where": "—", "kind": "step"}, {"unit": "FAC", "action": "تنفيذ الملاحظات الإنشائية والمعمارية (G-05 أو G-02)", "sla": "حسب المهلة", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "تجديد التراخيص قبل انتهائها", "sla": "قبل 60 يوماً", "where": "سجل التراخيص", "kind": "step"}, {"unit": "DIR", "action": "مراجعة حالة التراخيص والملاحظات المفتوحة", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'',406) on conflict (code) do nothing;
insert into public.gov_processes(code,title,owner,units,goal,trigger,inputs,outputs,kpi,steps,notes,sort) values ('H-07','السلامة المهنية للعاملين والمقاولين','SAF','["SAF", "MNT", "PRJ", "GEN", "DIR"]'::jsonb,'أن يعمل كل موظف ومقاول في إدارة الخدمات الفنية بطريقة آمنة: يعرف المخاطر، ويلبس معدات الوقاية، ويتوقف عند الخطر.','تعيين موظف أو بدء مقاول، أعمال جديدة الخطورة، أو حادث عمل.','تقييم مخاطر الأعمال، شروط السلامة في العقود، سجلات التدريب.','سجل تهيئة لكل عامل، تقارير تفتيش، سجل مخالفات وجزاءات.','100٪ من العمالة الجديدة بتهيئة سلامة قبل البدء؛ انخفاض إصابات العمل.','[{"unit": "SAF", "action": "تقييم مخاطر الأعمال لكل قسم فني (كهرباء، ارتفاعات، أحمال يدوية، أماكن محصورة) وتحديد معدات الوقاية", "sla": "سنوياً", "where": "سجل المخاطر", "kind": "step"}, {"unit": "PRJ", "action": "تضمين اشتراطات السلامة وجزاءاتها في وثائق الطرح والعقود", "sla": "قبل الطرح", "where": "وثائق الطرح", "kind": "step"}, {"unit": "SAF", "action": "تهيئة السلامة لكل عامل ومقاول جديد قبل بدء العمل، ثم إصدار البطاقة (H-05)", "sla": "قبل البدء", "where": "سجل التهيئة", "kind": "step"}, {"unit": "MNT", "action": "توفير معدات الوقاية الشخصية لعمالة الصيانة وإلزام المقاولين بها", "sla": "مستمر", "where": "—", "kind": "step"}, {"unit": "SAF", "action": "جولات تفتيش مفاجئة على مواقع الصيانة والمشاريع", "sla": "أسبوعياً", "where": "تقرير التفتيش", "kind": "step"}, {"unit": "SAF", "action": "إيقاف العمل فوراً عند خطر وشيك، وتوثيق المخالفة", "sla": "فوري", "where": "سجل المخالفات", "kind": "decision"}, {"unit": "PRJ", "action": "معالجة مخالفات مقاولي المشاريع وتطبيق الجزاءات التعاقدية (والصيانة لمقاوليها)", "sla": "أسبوع", "where": "—", "kind": "step"}, {"unit": "DIR", "action": "مراجعة مؤشرات السلامة المهنية", "sla": "ربع سنوي", "where": "—", "kind": "step"}]'::jsonb,'',407) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-19','كل حادث أو شبه حادث يُبلَّغ','الأمن والسلامة','يُبلَّغ عن كل حادث أو شبه حادث خلال 24 ساعة (فوراً للخطير)، ولا يُلام المبلِّغ عن شبه الحادث؛ الهدف منع التكرار.','["الإصابات والحرائق والحوادث الأمنية والانسكابات والأضرار", "أشباه الحوادث (كاد أن يقع)", "تحقيق بالسبب الجذري للمتوسط والخطير خلال 5 أيام عمل", "إجراءات تصحيحية بمسؤول ومهلة"]'::jsonb,'SAF','H-03','',19) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-20','لا مادة خطرة بلا جرد وبطاقة سلامة','الأمن والسلامة','لا تدخل مادة خطرة إلى منشأة إلا مدرجة في قائمة الجرد ومعها بطاقة بيانات السلامة (SDS) ومكان تخزين مطابق.','["قائمة جرد لكل منشأة وقسم", "بطاقة SDS متاحة في موقع الاستخدام", "ملصقات وفصل بين المواد غير المتوافقة", "طقم انسكاب قريب ومدرَّب عليه"]'::jsonb,'SAF','H-04','',20) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-21','لا دخول للمقاول بلا تهيئة وبطاقة','الأمن والسلامة','لا يبدأ عامل أو مقاول العمل داخل منشأة قبل تهيئة السلامة وإصدار بطاقة دخول سارية، ولا تُدخل المناطق المقيدة إلا بتصريح.','["تهيئة سلامة قبل اليوم الأول", "بطاقة باسم العامل والمقاول ومدة الصلاحية", "تصريح للمناطق المقيدة والحساسة", "سحب البطاقة عند انتهاء العقد"]'::jsonb,'SAF','H-05','',21) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-22','خطط الطوارئ تُختبر بتمارين','الأمن والسلامة','لكل منشأة خطة طوارئ معتمدة تُختبر بتمارين دورية موثقة، وتُحدَّث بعد كل حدث أو تمرين يكشف فجوة.','["تمرين حريق لكل منشأة ربع سنوياً", "تمرين إخلاء مرة سنوياً على الأقل", "تقرير تقييم لكل تمرين خلال 3 أيام", "إغلاق ملاحظات التمارين في مهلتها"]'::jsonb,'SAF','H-02','الدوريات مقترحة.',22) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-23','لا تشغيل قبل فحص السلامة','الأمن والسلامة','لا تُشغَّل مساحة جديدة أو معدّلة أو مُعاد فتحها إلا بعد فحص السلامة من الحريق (المخارج، الإنذار، الإطفاء، اللوحات) وموافقة الدفاع المدني حيث يلزم.','["ضمن الاستلام الابتدائي للمشاريع (G-04)", "ضمن جولة إعادة الفتح بعد الإغلاق (F-01)", "ضمن تغيير استخدام المساحات (G-12)"]'::jsonb,'SAF','H-06','',23) on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values ('R-24','للأمن والسلامة حق إيقاف العمل','الأمن والسلامة','يحق للأمن والسلامة إيقاف أي عمل فوراً عند خطر وشيك على الأشخاص أو المنشأة، ولا يُستأنف إلا بعد معالجة الخطر وتوثيقها.','["يشمل الصيانة ومقاوليها ومقاولي المشاريع", "توثيق المخالفة وإبلاغ القسم المسؤول", "الاستئناف بموافقة الأمن والسلامة"]'::jsonb,'SAF','H-07','',24) on conflict (code) do nothing;
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','خطط الطوارئ والإخلاء وتمارينها (H-02)','{"SAF": "R", "MNT": "C", "IT": "C", "FAC": "C", "GEN": "C", "DIR": "A"}'::jsonb,51 where not exists (select 1 from public.gov_activities where scope='units' and title='خطط الطوارئ والإخلاء وتمارينها (H-02)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','الإبلاغ عن الحوادث والتحقيق فيها (H-03)','{"SAF": "R", "MNT": "C", "FAC": "C", "DIR": "I"}'::jsonb,52 where not exists (select 1 from public.gov_activities where scope='units' and title='الإبلاغ عن الحوادث والتحقيق فيها (H-03)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','جرد المواد الخطرة وتخزينها والتخلص منها (H-04)','{"SAF": "R", "GEN": "R", "MNT": "C", "DIR": "I"}'::jsonb,53 where not exists (select 1 from public.gov_activities where scope='units' and title='جرد المواد الخطرة وتخزينها والتخلص منها (H-04)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','الحراسات وضبط الدخول والبطاقات والمفاتيح (H-05)','{"SAF": "R", "IT": "C", "MNT": "C", "DIR": "A"}'::jsonb,54 where not exists (select 1 from public.gov_activities where scope='units' and title='الحراسات وضبط الدخول والبطاقات والمفاتيح (H-05)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','أنظمة المراقبة والتحكم بالدخول (الكاميرات والبوابات)','{"IT": "R", "SAF": "A", "MNT": "C"}'::jsonb,55 where not exists (select 1 from public.gov_activities where scope='units' and title='أنظمة المراقبة والتحكم بالدخول (الكاميرات والبوابات)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','تراخيص الدفاع المدني وملاحظاته (H-06)','{"SAF": "R", "MNT": "R", "FAC": "C", "PRJ": "C", "DIR": "A"}'::jsonb,56 where not exists (select 1 from public.gov_activities where scope='units' and title='تراخيص الدفاع المدني وملاحظاته (H-06)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','فحص السلامة قبل تشغيل مساحة جديدة أو معدّلة (R-23)','{"SAF": "A", "PRJ": "R", "FAC": "C", "MNT": "C"}'::jsonb,57 where not exists (select 1 from public.gov_activities where scope='units' and title='فحص السلامة قبل تشغيل مساحة جديدة أو معدّلة (R-23)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','تهيئة السلامة للعاملين والمقاولين والتفتيش عليهم (H-07)','{"SAF": "R", "MNT": "C", "PRJ": "C", "GEN": "C"}'::jsonb,58 where not exists (select 1 from public.gov_activities where scope='units' and title='تهيئة السلامة للعاملين والمقاولين والتفتيش عليهم (H-07)');
insert into public.gov_activities(scope,grp,title,raci,sort) select 'units','ط. الأمن والسلامة','إيقاف العمل عند خطر وشيك (R-24)','{"SAF": "A", "MNT": "I", "PRJ": "I", "DIR": "I"}'::jsonb,59 where not exists (select 1 from public.gov_activities where scope='units' and title='إيقاف العمل عند خطر وشيك (R-24)');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'FAC','SAF','إشعار إغلاق معتمد','الغرف والمدة لتقييم مسارات الإخلاء وتأمين المنطقة','قبل 48 ساعة','F-01','',30 where not exists (select 1 from public.gov_handoffs where from_unit='FAC' and to_unit='SAF' and trigger='إشعار إغلاق معتمد');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'BEN','SAF','حريق أو حادث أمني أو إصابة أو انسكاب مواد خطرة','اتصال فوري ثم بلاغ حادث بالموقع والتفاصيل','فوري؛ البلاغ خلال 24 ساعة','H-03','',31 where not exists (select 1 from public.gov_handoffs where from_unit='BEN' and to_unit='SAF' and trigger='حريق أو حادث أمني أو إصابة أو انسكاب مواد خطرة');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'PRJ','SAF','قبل مباشرة أعمال داخل منشأة مشغّلة','خطة السلامة للموقع وقائمة العمالة للتهيئة والبطاقات','قبل أسبوع','G-10','',32 where not exists (select 1 from public.gov_handoffs where from_unit='PRJ' and to_unit='SAF' and trigger='قبل مباشرة أعمال داخل منشأة مشغّلة');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'PRJ','SAF','قبل الاستلام الابتدائي أو تشغيل مساحة جديدة','دعوة لفحص السلامة من الحريق والمخارج','قبل موعد اللجنة بأسبوع','G-04','',33 where not exists (select 1 from public.gov_handoffs where from_unit='PRJ' and to_unit='SAF' and trigger='قبل الاستلام الابتدائي أو تشغيل مساحة جديدة');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'SAF','FAC','ملاحظات سلامة من الجولات أو التمارين أو الدفاع المدني تحتاج إصلاحاً','قائمة ملاحظات بالأولوية والمهلة','خلال يومين','H-06','',34 where not exists (select 1 from public.gov_handoffs where from_unit='SAF' and to_unit='FAC' and trigger='ملاحظات سلامة من الجولات أو التمارين أو الدفاع المدني تحتاج إصلاحاً');
insert into public.gov_handoffs(from_unit,to_unit,trigger,deliverable,sla,process_code,note,sort) select 'SAF','DIR','نهاية كل شهر','تقرير الحوادث والمؤشرات وحالة التراخيص','خلال 5 أيام','H-03','',35 where not exists (select 1 from public.gov_handoffs where from_unit='SAF' and to_unit='DIR' and trigger='نهاية كل شهر');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف أبلّغ عن حادث أو إصابة أو شبه حادث؟','الحدث الجاري (حريق، اعتداء) طوارئ: اتصال فوري بالأمن والسلامة (G-11). وكل حادث أو شبه حادث يُبلَّغ خلال 24 ساعة بنموذج بلاغ الحادث مع الموقع ورقم الغرفة؛ يصنّفه الأمن والسلامة ويحقق في أسبابه خلال 5 أيام عمل ويتابع الإجراءات التصحيحية (H-03، R-19).','["H-03", "R-19", "G-11"]'::jsonb,'',22 where not exists (select 1 from public.gov_faq where q='كيف أبلّغ عن حادث أو إصابة أو شبه حادث؟');
insert into public.gov_faq(q,a,links,action,sort) select 'من يتولى خطط الطوارئ وتمارين الإخلاء؟','الأمن والسلامة (H-02): تحليل المخاطر لكل منشأة، خطة برموز الطوارئ ومسارات الإخلاء، تمرين حريق ربع سنوي وإخلاء سنوي على الأقل، وتقرير لكل تمرين. الصيانة تضع خطة استمرارية المرافق، والمنشأة تدرّب طاقمها (R-22).','["H-02", "R-22"]'::jsonb,'',23 where not exists (select 1 from public.gov_faq where q='من يتولى خطط الطوارئ وتمارين الإخلاء؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف نتعامل مع المواد الخطرة أو انسكابها؟','لا تدخل مادة خطرة إلا مدرجة في قائمة الجرد ومعها بطاقة بيانات السلامة (R-20). الانسكاب يُبلَّغ فوراً ويُحتوى بطقم الانسكاب، ثم يحقق فيه الأمن والسلامة (H-04، H-03).','["H-04", "R-20"]'::jsonb,'',24 where not exists (select 1 from public.gov_faq where q='كيف نتعامل مع المواد الخطرة أو انسكابها؟');
insert into public.gov_faq(q,a,links,action,sort) select 'كيف يدخل مقاول أو عامل جديد إلى منشأة؟','بعد تهيئة السلامة وإصدار بطاقة دخول سارية من الأمن والسلامة؛ لا دخول بلا بطاقة، والمناطق المقيدة بتصريح (H-07، H-05، R-21).','["H-05", "H-07", "R-21"]'::jsonb,'',25 where not exists (select 1 from public.gov_faq where q='كيف يدخل مقاول أو عامل جديد إلى منشأة؟');
insert into public.gov_faq(q,a,links,action,sort) select 'من يتابع تراخيص الدفاع المدني وملاحظاته؟','الأمن والسلامة (H-06): سجل التراخيص وتجديدها قبل 60 يوماً، الفحص الشهري للطفايات والمخارج واللوحات، مرافقة زيارات الدفاع المدني وخطة معالجة ملاحظاتها، وفحص السلامة قبل تشغيل أي مساحة جديدة (R-23).','["H-06", "R-23"]'::jsonb,'',26 where not exists (select 1 from public.gov_faq where q='من يتابع تراخيص الدفاع المدني وملاحظاته؟');
insert into public.gov_faq(q,a,links,action,sort) select 'من يوقف عملاً خطراً في الموقع؟','للأمن والسلامة حق إيقاف أي عمل فوراً عند خطر وشيك، ولا يُستأنف إلا بعد المعالجة وموافقته (R-24، H-07).','["R-24", "H-07"]'::jsonb,'',27 where not exists (select 1 from public.gov_faq where q='من يوقف عملاً خطراً في الموقع؟');
insert into public.gov_router(key,q,opts,sort) values ('safety','ما نوع الحالة؟','[{"t": "حريق أو حادث أمني جارٍ الآن", "out": {"proc": "G-11", "unit": "SAF", "title": "طوارئ — الأمن والسلامة", "text": "اتصل فوراً بالأمن والسلامة وفعّل رمز الطوارئ؛ الإخلاء وفق خطة المنشأة، ويُسجَّل البلاغ لاحقاً."}}, {"t": "حادث وقع أو إصابة أو شبه حادث", "out": {"proc": "H-03", "unit": "SAF", "title": "الأمن والسلامة — بلاغ حادث", "text": "بلاغ حادث خلال 24 ساعة بالموقع ورقم الغرفة؛ تحقيق بالسبب الجذري خلال 5 أيام عمل."}}, {"t": "انسكاب أو تخزين مواد خطرة", "out": {"proc": "H-04", "unit": "SAF", "title": "الأمن والسلامة — المواد الخطرة", "text": "احتواء فوري بطقم الانسكاب وإبلاغ الأمن والسلامة؛ ولكل مادة خطرة جرد وبطاقة سلامة."}}, {"t": "مخرج مسدود، طفاية، باب حريق، إنذار معطل", "out": {"proc": "H-01", "unit": "SAF", "title": "الأمن والسلامة — السلامة من الحريق", "text": "يُسجَّل فوراً ويُعالج مع الصيانة، مع إجراءات بديلة إن طال التعطيل."}}, {"t": "دخول مقاول، بطاقات، مفاتيح، ملاحظة أمنية", "out": {"proc": "H-05", "unit": "SAF", "title": "الأمن والسلامة — الأمن وضبط الدخول", "text": "تهيئة سلامة ثم بطاقة دخول سارية؛ المناطق المقيدة بتصريح."}}]'::jsonb,7) on conflict (key) do nothing;
update public.gov_router set opts = opts || '[{"t": "أمن أو سلامة: حادث، إصابة، حريق، مواد خطرة، دخول", "next": "safety"}]'::jsonb where key='start' and not opts::text like '%"next": "safety"%';
